import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"賁","description":"高岛易断 - 賁","frontmatter":{"title":"賁","description":"高岛易断 - 賁"},"headers":[],"relativePath":"zh/classics/takashima/022.md","filePath":"zh/classics/takashima/022.md"}'),i={name:"zh/classics/takashima/022.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="賁" tabindex="-1">賁 <a class="header-anchor" href="#賁" aria-label="Permalink to “賁”">​</a></h1><h2 id="賁-1" tabindex="-1">賁 <a class="header-anchor" href="#賁-1" aria-label="Permalink to “賁”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>贲：亨，小利有攸往。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《贲》卦上体山，山蕴质素，下体火，火吐文光，下火上烛，则质而有文，故曰《贲》。文质交错，刚柔得中，故曰“亨”。《离》火之明，遇山而止，则所进者小矣，故曰“小利有攸往”。其义，则《彖》辞详之矣。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>山下有火，贲，君子以明庶攻，无敢折狱。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>《艮》山之下有《离》火，《艮》，一阳高出二阴之上，阳塞于外而不通，故止；《离》，二阳之中含一阴，是内虚而含明，故明。君子法之，“以明庶政”，“庶政”者，或兼教养，或兼兵食，《洪范》所谓“八政”皆是也。暗则紊，明则治，取之高，而政教明矣。明以致察，过察则失严，故于折狱，则曰“无敢”。“无敢”者，谓不敢自用其明也。虚明之心存于中，而慈祥之政行于外，明其所当明，而不敢过用其明，取之于《艮》，明于是乎止焉。丰田“致刑”，以“明而动”，贲曰“无敢”，以明而止。不动则民不畏法，不止则民不聊生，有相济而行也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：目下正当发动，百事顺适，但上有阻止，未能遂意径行。</p><p>○　问商业：主经理人才干强明，足以任事；但精明者必刻利，还宜留意。</p><p>○　问家宅：恐宅中时有火光发动，幸即扑灭，无大害也。</p><p>○　问战征：前面有山，未易进攻。</p><p>○　问疾病：是郁火上蒸之症，宜息火，犹不可过用寒剂，致真火扑灭。</p><p>○　问行人：欲归又止，尚未定也。</p><p>○　问六甲：生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初刚在下，故曰贲趾，“徒”，徒行也。古者从大夫之后，不可徒行，初无位，故“舍车而徒”。贲趾者，是践仁履义，以仁义“贲其趾”者也，不以乘车为贲，而以徒行为贲。乘车者，世之所贲，君子所耻，是以舍之。《象传》曰“义弗乘也”，喜初之能守义也。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问时运：生性清高，不合时趋，以德亨，不以名亨。</p><p>○　问商业：必是肩负买卖，非舟车贩运之业，虽小亦亨。</p><p>○　问家宅：是勤俭起家，颇有知足不辱之风。</p><p>○　问战征：陆军利。</p><p>○　问行人：中途遇阻，步行而归。</p><p>○　问疾病：症在初起，不食药而可愈也。</p><p>○　问讼事：恐有惩役之灾。</p><p>○　问失物：已舍去之，寻觅徒劳。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>明治十九年，占某贵显气运，筮得《贲》之《艮》。</p><p>断曰：此卦上《艮》下《离》，所谓高山仰止者，某贵显之德望也；所谓高明遍照者，某贵显之功业也，是当今所共知者也。现时退位闲居，今占得《贲》初九，曰“贲其趾，舍车而徒”，爻象正合。初爻为无位，阳刚在下，贲，有文也；趾，足也，从止，有退归之象。“舍车”，犹舍位而隐也，“徒”，行也，将复起也。舍车徒行，是某贵显将潜行民间，窥察民情风俗，以益光文明之治，补维新以来所未修，是某贵显之隐衷也，爻象以明示之。在某贵显为维新元勋，虽暂退间，其心头岂一日忘天下哉！兹值初爻，贲犹未光，至三而贲盛，至六犹能反其贲，以协于中。贲之运正长，知某贵显，后日必德望愈隆，功业愈大也。《彖》所谓“观乎天文，以察时变，观乎人文，以化成天下”，皆可于某贵显见之。后果如此占。今辅佐朝政，望同山斗，遇际明良，是《贲》之所以为《贲》也。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>二以柔居柔，其爻自《噬嗑》六五柔来，变为六二，即《彖传》所谓“柔来而文刚”也。取象于颐，此爻曰“须”，须，随颐而动，故注曰：须之为物，上附者也。柔来文刚，文刚者，贲也，故曰“贲其须”。须眉为人生之仪表，所谓严其瞻视者，此也。《象传》曰“与上兴也”，“上”，谓上卦《噬嗑》，“兴”，动也。《噬嗑》内卦为《震》，《震》为动，须附上，爻自《噬嗑》来，故曰“与上兴也”。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：目下平平，只可依人成事。</p><p>○　问商业：与富商合业，必大兴旺，吉。</p><p>○　问战征：必须与大军同进，方可得胜。</p><p>○　问家宅：叨上人之福泽，藉以光大门楣。</p><p>○　问婚嫁：“归妹以须，”尚宜待也。</p><p>○　问六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治十四年四月占国会。方今我国舆论，咸愿开设国会，群议纷纷，未可臆断，特占一卦，得《贲》之《大畜》。</p><p>断曰：此卦自二至上为五年，其间不见凶咎。《贲》下卦为《剥》，《剥》之上即第六年，其凶尤甚。今审度避凶趋吉之方，须就变卦《大畜》探索。为之先说《贲》终《剥》来之凶象，复述变卦《大畜》之卦义。《彖》辞曰：“贲亨，小利有攸往”。贲者文饰也，凡事饰于外者，必由其内有缺乏也。今当开设国会，各府县推举代议士，才力学识，未必完全，多皆徒施外饰而已。《彖传》曰“柔来而文刚，”刚上而文柔”，谓上卦之柔，来贲下卦之刚，下卦之刚，上贲上卦之柔，上下各以刚柔，互相贲饰，此《彖传》义也。今拟之国会，上卦为官吏，下卦为代议士，各以论说相抵抗者也。曰“贲亨”，知国会之事无不亨通；曰“小利有攸住”，知国会虽可进行，未免有所退止也；曰“观乎天文，以察时变”，谓当察时机之会，审宇内之势，以维持国体于不朽也；曰“观乎人文，以化成天下”，谓应民心之归向，文运之昌明，开设国会，上下合志，可以计划国家之安宁。此就《彖传》义而释之如是，进推六爻，初爻“贲其趾”，舍车而徒”。初爻在下，是无位也，谓微贱下民，亦将持杖徒行，奔走而来观德化也。二爻“贲其须，”《象传》曰“贲其须，与上兴也，”二虽进初一等，其人不能自主，随人之议论以为议论，如须之随颐而动也。三爻“贲如濡如，永贞吉，”《象传》释之曰：“永贞之吉，终莫之陵也。”三居下卦之上，近比四爻，“贲如濡如”，贲之盛也。三以阳居阳，卦中为主贲，会中为主议，持论不易，能守“永贞”，故吉。《象》谓“终莫之陵”，言无与相抗也。四爻“贲如皤如，白马翰如，匪寇婚媾”，此爻为政府地位，与三接近。“贲如皤如”者，谓官吏示以从前政府施行之事状；“白马翰如”者，谓听者解得政府之实情；“匪寇婚媾”者，谓感官吏之勤劳，相与辅翼而赞成之也。五爻“贲于丘园”，“束帛戋戋”，谓议士中有知“丘园”之贤士，推荐于朝，当具“束帛”以招之，使之出而共议国是，故“终吉”。上爻“白贲，无咎”，乃退位老臣，谓创兴国会，未免近于粉饰，终宜黜华崇实，是返本之道也。从此节财省费，得谋裕国之策也。《贲》之终，《剥》之始也，更论《剥》卦之义。《剥》《彖传》曰：“剥，剥也，柔变刚也。不利有攸往，小人长也。”“柔变刚”者，是“小人道长”之时也，故曰“不利有攸往”，戒辞也。初爻曰“剥床以足，蔑贞凶，”阴之剥阳，自下而上，邪害正也，谓有武人，恶人民之渐进逼上，欲压灭其党类之象。二爻曰“剥床以辨，蔑贞凶”，“辨”者床干也，指党类之长，初爻既灭党类，今又欲殄灭其长之象。三爻曰“剥之无咎”，其党类为时势所激，忽起变志，不复顾忌名分，是最不祥之占也。四爻曰“剥床以肤，凶”，有众阴逼上之势，渐逼渐近，其凶更甚。五爻曰“贯鱼以宫人宠，无不利”，谓剥之者凶，顺之则利，有一时委曲保全之象。上爻曰“硕果不食。君子得舆，小人剥庐”，谓虽当剥极，必有硕果之仅存者，君子处之，谓终得爱戴，小人处之，谓无所容身，是小人欲剥君子，自己亦罹其灾之谓也。以上自《贲》移《剥》之卦象也。贲为文明而止之卦，方今人情，徒慕欧英文化，不察时势之可否，难免剥落之灾，如《剥》卦所述，故君子必贵思患而预防也。今占得《贲》之《大畜》，再释《大畜》之义，以示占者。《大畜》《彖传》曰：“大畜，刚健，笃实，辉光，日新其德。刚上而尚贤，能止健，大正也。不家食吉，养贤也。利涉大川，应乎天也。”《大畜》者，畜之大者也，专在尚宾养贤，以为国家用，足以黼黻太平也。初爻曰“有厉利己”，《象传》曰：“有厉利己，不犯灾也。”初以四为正应，欲进而四畜之，即为艮所抑，有不能达志之象。二爻曰“舆脱輹”，《象传》曰：“舆脱輹，中无忧也。”二爻见初三两爻之止，有同愿屈抑之象。三爻曰：“良马逐，利艰贞，日闲舆卫，利有攸往。”《象传》曰：“利有攸往，上合志也。”三爻以刚健之才，欲锐进而从事者也，为四畜之，使不得进，遂变其志向，谋开垦牧畜等事。曰“良马逐”，曰“利艰贞”，皆开拓牧畜之象。又曰“闲舆卫”，曰“利有攸往”，并习练军事之象。如是有益政府，故谓之“上合志也”。四爻曰“童牛之牿，元吉”，《象传》曰：“六四元吉，有喜也。”此爻当县官地位，县官能使无产士族，从事牧畜开垦等事，犹牧童牛，易畜易制之谓也。五爻曰“豮豕之牙，吉”，《象传》曰：“六五之吉，有庆也。”此爻亦与六四同。上九曰“荷天之衢，亨”，《象传》曰“荷天之衢，道大行也”，谓全国士民各得其所，天下泰平之象也。以上国会之占断如此。至翌年七月，政府颁示实施政令三条：一发布明治二十三年开设国会之令；一为救济无资士族，与以八十万元之授产金；一政府锐意开造铁路，计划中山道及奥羽之布设，与以年八朱之利息保护。皆呈象于《大畜》之爻义，得时势之宜者也。《易》象之灵妙如此。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>三以一刚介二阴之间，当贲之盛，“贲如濡如，”润泽之象。顾阴能贲人，亦能溺人，诫之以“永贞”，在我有常贞之操，斯彼无凌逼之嫌，故曰“吉”。《象传》曰“永贞之吉，终莫之凌也”，“终”字与“永”字相应，盖贞而不永，则非有终者也。谓我刚正而永贞，彼自不能凌侮也。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问时运：当此盛运，光华润泽，名利双收，大亨。</p><p>○　问商业：财源如水，大得清润，基业亦可保长久，大吉。</p><p>○　问家宅：屋宇华洁，又得流水掩映，可以久居，吉。</p><p>○　问战征：一军皆感被德泽，欢洽同心，可称王师无敌。</p><p>○　问讼事：得直，彼亦不敢复犯。</p><p>○　问婚嫁：百年偕老，吉。</p><p>○　问六甲：生男。</p><p>○　问行人：衣锦荣耀而归。</p><p>○　问失物：向水中寻之，得。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>友人某来，请占气运，筮得《贲》之《颐》。</p><p>断曰：此卦一阳居二阴之中，如物入水中，沾濡润泽，光彩益章，故曰“贲如濡如”，贲之盛也。然贲饰过甚，外耀有余，往往内美不足，是贲之流弊也。今我国自维新以来，仕途一变，每多有自炫才华，以冀仕进，饰智惊愚，互相标榜，大都如斯。迨一旦得位，毫无寸能，此辈纯盗虚声者，固可暂而不可“永贞”者也，吉何有焉？足下有意当世，宜践实德，毋博虚名，持之以“贞”，守之以“永”，终得吉也。《象传》曰：“终莫之凌”。谓贲非虚贲，人复谁能相抗也。足下其留意焉！</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>四在上卦之下，《贲》已过中。“皤”，素白色也，“翰”，白色马也。卦体三、四、五互《震》，《震》为白马，故取白马之象。《震》上六曰“婚媾”，故亦有婚媾之象。四与初为正应，为三所隔，不获相贲，故曰“皤如”，“白马翰如”，亦未获其贲也。然九三刚正，“非寇”，乃求婚媾耳。四与初正应，必相亲贲，不能终隔也。《象传》曰“当位疑”，四疑二也。曰“终无尤”，谓初四正应。终必相合，故云“终无尤”也。</p><h2 id="六四占" tabindex="-1">六四占 <a class="header-anchor" href="#六四占" aria-label="Permalink to “六四占”">​</a></h2><p>○　问时运：目下运有阻碍，安分则吉，明年便可亨通。</p><p>○　问商业：宜迅疾贩售，迟缓，防货物变色。</p><p>○　问家宅：一宅之内，既有丧事，又逢婚事，前塞后通，无咎。</p><p>○　问战征：有和亲通好之议。</p><p>○　问疾病：中胸有阻，故上下不调，积阻消化，便无咎也。</p><p>○　同行人：有爱女眷恋，一时未归。</p><p>○　问六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>有人来，请占某缙绅气运，筮得《贲》之《离》。</p><p>断曰：四以阴居阴，与初为正应，为中间三爻所隔，不获相贲相亲，《象传》曰“当位疑也”。今占得四爻，知某缙绅在局，或亦因中有间阻，致生疑虑之处，然其中乘马翰如而来者，实欲相与亲密，并无他意。四爻初则疑之为寇，为将攘夺我利也，至后渐知其真，疑念始解，故曰“匪寇婚媾”。当时某缙绅确有是事，初疑后解，两情甚洽，果如此占。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>“丘园”者，园之依丘陵者。艮有丘之象，“贲于丘园”者，谓留意于农桑之事。“束帛”者，赠人之物，“戋戋”者，浅少之意。不贲市朝而贲丘园，敦本也。“束帛戋戋”，谓六五以柔居尊位，能修柔中之德，黜祛奢华，敦崇俭约，如大禹之卑宫室，菲饮食也，故曰“贲于丘园，束帛戋戋”。“吝”，谓居尊位，而留心鄙事，未免吝也，然不失黜华崇实之旨，故曰“终吉”。《象传》曰“有喜也”，有喜者，谓实有可喜也。天下之俗成于俭，败于奢，一人倡之，世风可返于淳朴，则所喜非在一人，喜其能移风易俗也。一说，丘园为隐士所居，六五能以“束帛”，聘求丘园之遗贤，共辅文明之治。聘贤仅以“戋戋”束帛，礼意未隆，故曰“吝”；在贤者不以币帛为悦，而以恭敬为悦，是以币帛虽微，贤者亦应聘而来，故终有吉也。亦通。</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问时运：目下恰行正运，然作事一宜俭勤为吉。</p><p>○　问商业：买卖最直木材绸物二行，货物不必多，而获利颇佳。</p><p>○　问家宅：农桑为业，勤俭家风，吉。</p><p>○　问战征：宜招用野老，以作向导，可以得胜。</p><p>○　问婚嫁：聘礼虽微，却好得一贤妇，大喜。</p><p>○　问六甲：生男。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>友人来，请占气运，筮得《贲》之《家人》。</p><p>断曰：此爻为五居尊位，崇尚俭德，将率天下而从俭也，故不贲宫殿，而贲丘园。“束帛”之礼，以诚相将，不尚丰厚。今占得此爻，知足下自幼从事商业，一番辛勤，得有今日，资产丰裕，亦足自乐。近来商业，多习欧美之风，全以欺诈为术，华丽自夸，反以曩时朴素敦厚为可吝也。在吾辈敦尚古风者，不屑与之较也，足下惟当安闲，觅一山林佳处，修筑园榭，栽植花木，以娱心目，为作养老之计也。人或以吾辈不事世事为吝，然以此而娱老，以此而传后，终得吉也，谓之“贲于丘园，束帛戋戋，吝，终吉”也。友人从此占，亦足自乐。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上处《贲》之终，终极不变，弊将无质，故《贲》之义，始因天下之质，饰之以文，并将天下之文，归之于质。“白贲”者，素朴自然，是无色也，如宝玉不雕，珍珠不饰，不使文掩其质，“白贲”之谓也。《象传》曰“上得志也”，居卦之上，处事之外，矫世俗之文饰，而敦尚朴素，独行其专，优游自得耳。凡卦如《泰》与《否》、《剥》与《复》、《涣》与《萃》等，皆有对偶，惟《贲》无对，独于卦中，分贲与不贲两义为对。是读《易》之诀也。《中孚》一卦亦然。</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问时运：好运已终，劳者宜归于逸，动者宜返于静，优游自适，聊以取乐耳。</p><p>○　问商业：现在货价已高，时令将完，不必装饰，即可出售，定得利也。</p><p>○　问家宅：清白家风，位置亦高，吉。</p><p>○　问战征：身当上将，堂堂之阵，正正之旗，不用谲计奇谋，自然获胜。吉。</p><p>○　问疾病：病在上焦，宜用清淡之剂，吉。</p><p>○　问行人：得利归来。</p><p>○　问六甲：生男。</p><p>○　问失物：向高处寻觅，可得。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>维新之际，浦贺管署吏员下村三郎左卫门，旧佐贺藩之士也，罹病日久，来横就医。医曰：病似轻而实重，非滞留受治，恐至危殆。下村氏告于长官，许以留医。下村氏不以病为虑，强还任地，长官谓余曰：下村氏之疾如何？子试筮之。筮得《贲》之《明夷》。</p><p>断回：下村氏必死。长官曰：医亦视为重症，但子何以豫言其死也？余曰：《贲》者上山下火，今山变而为地，是《离》明没于《坤》地之象。上九阳变而为阴，阳者生也，阴者死也，即生变为死之象。又上九之爻辞曰“白贲”，白者丧服也，其死不免矣。后未一月，果接其讣音。</p>',98)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
